class Solution {
    public int numProvinces(int[][] adj) {

        //Visited array that tells if each city is visited or not.
        boolean[] vis = new boolean[adj.length];

        int count = 0;

        //looping over visited array and doing standard dfs
        for(int i=0;i<vis.length;i++){
            if(vis[i] == false){
                count++;
                dfsRec(i,adj,vis);
            }
        }

        return count;
    }

    private void dfsRec(int city,int[][] adj,boolean[] vis){
        vis[city] = true;

        for(int k = 0 ;k< adj[city].length; k++){

            //if the city is not visited && there is no self reference && there is edge between two cities 
            // edge is rep as adj[i][j] 
            // mark that city as visited 
            if(vis[k]==false && city != k && adj[city][k]== 1){
                dfsRec(k,adj,vis);
            }

        }
    }
}

