class Solution {

    public void dfs(ArrayList<ArrayList<Integer>> adjList, int[] visited, int node) {
        visited[node] = 1;

        for (int next : adjList.get(node)) {
            if (visited[next] == 0) {
                dfs(adjList, visited, next);
            }
        }
    }

    public int numProvinces(int[][] adj) {

        int v = adj.length;

        ArrayList<ArrayList<Integer>> adjList = new ArrayList<>();

        for (int i = 0; i < v; i++) {
            adjList.add(new ArrayList<>());
        }

        for (int i = 0; i < v; i++) {
            for (int j = 0; j < v; j++) {
                if (adj[i][j] == 1 && i != j) {
                    adjList.get(i).add(j);
                }
            }
        }

        int[] visited = new int[v];
        int count = 0;

        for (int i = 0; i < v; i++) {
            if (visited[i] == 0) {
                count++;
                dfs(adjList, visited, i);
            }
        }

        return count;
    }
}
